package org.transittr.tests;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
/** Focused regression: explicit line request, real UI wiring and truthful passed-bus ETAs. */
public final class EgoLineCheck extends Instrumentation {
 private Activity activity;private volatile boolean sample;private int peak,count;
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private Object field(String name)throws Exception{Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private void status(String value){Bundle b=new Bundle();b.putString("stream",value+"\n");sendStatus(1,b);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();Thread sampler=null;boolean passed=false;try{
  sample=true;sampler=new Thread(new Runnable(){public void run(){while(sample){Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);peak=Math.max(peak,info.getTotalPss());count++;try{Thread.sleep(100);}catch(InterruptedException done){return;}}}});sampler.start();
  activity=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();ClassLoader loader=activity.getClassLoader();Class<?> ego=loader.loadClass("org.transittr.EgoMobile"),tracker=loader.loadClass("org.transittr.TrackingClient");Method url=ego.getMethod("requestUrl",String.class,String.class);
  String stop=(String)url.invoke(null,"10940","");check(stop.contains("FNC=Otobusler&")&&!stop.contains("HAT="),"unfiltered stop endpoint");String line=(String)url.invoke(null,"10940","481");check(line.contains("FNC=Otobus&")&&line.contains("HAT=481"),"all vehicles line endpoint");try{url.invoke(null,"10940","481&FNC=x");throw new AssertionError("query injection accepted");}catch(InvocationTargetException expected){check(expected.getCause() instanceof java.io.IOException,"validation error");}
  String json="{\"status\":\"TRUE\",\"table\":[{\"arac_no\":\"A\",\"hat_no\":\"481\",\"hat_kisa_kod\":\"481-6\",\"lat\":\"39.9\",\"lng\":\"32.8\",\"saniye\":\"999999\"},{\"arac_no\":\"B\",\"hat_no\":\"481\",\"hat_kisa_kod\":\"481-6\",\"lat\":\"39.91\",\"lng\":\"32.81\",\"saniye\":\"120\"},{\"arac_no\":\"C\",\"hat_no\":\"481\",\"hat_kisa_kod\":\"481-6\",\"lat\":\"39.92\",\"lng\":\"32.82\",\"saniye\":\"60\",\"sure\":\"Geçti\"},{\"arac_no\":\"-\",\"lat\":\"39.9\",\"lng\":\"32.8\"}]}";
  Object snapshot=tracker.getMethod("ankara",String.class,String.class).invoke(null,json,"481");ArrayList rows=(ArrayList)snapshot.getClass().getField("rows").get(snapshot);check(rows.size()==3,"multiple vehicles, internal line code and scheduled exclusion");Object first=rows.get(0);check("2 dk".equals(first.getClass().getField("eta").get(first)),"upcoming sorted first");for(int i=1;i<3;i++){Object row=rows.get(i);check("Geçti".equals(row.getClass().getField("eta").get(row)),"sentinel and text passed status");}
  status("EGO_LINE_FIXTURES_PASS=7");
  runOnMainSync(new Runnable(){public void run(){try{Method stop=activity.getClass().getDeclaredMethod("stopTracking");stop.setAccessible(true);stop.invoke(activity);Field city=activity.getClass().getDeclaredField("city");city.setAccessible(true);city.setInt(activity,0);Field screen=activity.getClass().getDeclaredField("screen");screen.setAccessible(true);screen.setInt(activity,0);Field data=activity.getClass().getDeclaredField("snapshot");data.setAccessible(true);data.set(activity,null);Method build=activity.getClass().getDeclaredMethod("build");build.setAccessible(true);build.invoke(activity);((EditText)field("stopInput")).setText("10940");((EditText)field("lineInput")).setText("481");((Button)field("start")).performClick();}catch(Exception e){throw new RuntimeException(e);}}});
  Object live=null;for(int i=0;i<200;i++){Thread.sleep(200);waitForIdleSync();live=field("snapshot");if(live!=null)break;}check(live!=null,"real line query completed");int vehicles=((Integer)live.getClass().getMethod("positionCount").invoke(live)).intValue();check(vehicles>1,"line returns multiple real GPS vehicles");status("LIVE_EGO_LINE=481; STOP=10940; VEHICLES="+vehicles);status("CAPTURE=EGO_LINE_MAP");Thread.sleep(6000);passed=true;result.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; EGO_LINE=481; VEHICLES="+vehicles+"; PEAK_PSS_KIB="+peak+"; SAMPLES="+count+"\n");
 }catch(Throwable e){java.io.StringWriter out=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(out));result.putString("stream","FAIL Android "+Build.VERSION.SDK_INT+"\n"+out);}finally{sample=false;if(sampler!=null)sampler.interrupt();}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
